"""Build a self-contained offline HTML listening page from verified exports."""
import base64,io,json,math,wave
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'artifacts/listening_20261111'
d=json.loads((folder/'export.json').read_text())
assert len(d['samples'])==20 and len(d['models'])==3
for sample in d['samples']:
    assert len(sample['tracks'])==5
    for t in sample['tracks'].values():
        with wave.open(io.BytesIO(base64.b64decode(t['wav']))) as f:
            assert (f.getnchannels(),f.getframerate(),f.getnframes(),f.getsampwidth())==(1,16000,64000,2)
        assert all(math.isfinite(v) for v in t['envelope'])
DATA=json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
html='''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>听见目标 · TF-TSE 试听对照</title>
<style>
:root{--paper:#f5f4ee;--ink:#182b2b;--muted:#61716c;--line:#dce1d8;--green:#17745b;--amber:#a25922}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}header{background:#142f2d;color:#f2f6ec;padding:48px max(24px,calc((100vw - 1320px)/2));position:relative;overflow:hidden}header:after{content:"";position:absolute;width:380px;height:380px;border:1px solid #426059;border-radius:50%;right:4%;top:-190px;box-shadow:0 0 0 50px #ffffff04,0 0 0 100px #ffffff03;pointer-events:none}.eyebrow{font-size:12px;letter-spacing:.18em;color:#a9c9b6;text-transform:uppercase}h1{font-size:clamp(32px,4vw,52px);line-height:1.2;letter-spacing:-.04em;margin:12px 0 18px}header p{max-width:740px;color:#c4d5cb;margin:0}.chips{display:flex;gap:12px;margin-top:25px;flex-wrap:wrap}.chips span{border:1px solid #416159;padding:4px 12px;border-radius:20px;font-size:12px}main{max-width:1368px;margin:auto;padding:26px 24px 60px}.note{background:#e9eee4;border-left:3px solid var(--green);padding:14px 18px;margin-bottom:20px}.note strong{color:var(--green)}.toolbar{position:sticky;top:0;background:#f5f4eef5;backdrop-filter:blur(10px);padding:15px 0;z-index:4;border-bottom:1px solid var(--line)}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.controls+.controls{margin-top:10px}.caption{font-size:12px;color:var(--muted);min-width:50px}button,select{font:inherit;font-size:13px;border:1px solid #cdd5ca;background:#fff;border-radius:7px;padding:7px 12px;color:var(--ink);cursor:pointer}button:hover{border-color:var(--green)}button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}button:focus-visible,select:focus-visible{outline:3px solid #75b79a;outline-offset:2px}.stop{margin-left:auto}.section-title{margin:34px 0 16px;display:flex;justify-content:space-between;align-items:baseline;gap:15px}.section-title h2{font-size:24px;letter-spacing:-.03em;margin:0}.section-title span{color:var(--muted);font-size:13px}.sample{border:1px solid var(--line);border-radius:13px;background:#fff;margin-bottom:20px;overflow:hidden}.sample-top{padding:17px 20px;display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid #e8ece5}.sample-top h3{font-size:17px;margin:0 0 4px}.sample-top p{font-size:12px;color:var(--muted);margin:0}.badge{display:inline-block;font-size:12px;padding:2px 8px;border-radius:4px;margin-right:8px;background:#e7eee4;color:#365b43}.badge.absent{background:#faecdc;color:#92501e}.tracks{display:grid;grid-template-columns:repeat(5,minmax(0,1fr))}.track{padding:16px 14px;border-right:1px solid #edf0ea;min-width:0}.track:last-child{border:0}.track-label{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:600}.track-label small{color:var(--muted);font-size:10px;font-weight:400}.wave{width:100%;height:40px;display:block;margin:10px 0;color:#79a68e}.input .wave{color:#a5aca1}.target .wave{color:#6c949b}audio{width:100%;height:34px;display:block}.metric{font-size:12px;margin-top:11px;color:var(--muted);min-height:40px}.metric b{font-size:16px;color:var(--green);font-variant-numeric:tabular-nums}.metric b.negative{color:var(--amber)}.small{font-size:11px;color:var(--muted)}details{border-top:1px solid #edf0ea;padding:9px 20px;font-size:12px;color:var(--muted)}summary{cursor:pointer}details p{word-break:break-all;margin:8px 0}#empty{padding:40px;text-align:center;color:var(--muted)}footer{margin-top:35px;border-top:1px solid var(--line);padding-top:20px;color:var(--muted);font-size:12px}.legend{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:22px 0}.legend p{margin:4px 0;font-size:13px;color:var(--muted)}.legend strong{font-size:14px}.off{display:none!important}[hidden]{display:none!important}@media(max-width:1050px){.tracks{grid-template-columns:repeat(3,minmax(0,1fr))}.track{border-bottom:1px solid #edf0ea}}@media(max-width:650px){header{padding:32px 20px}.tracks{grid-template-columns:1fr}.track{border-right:0}.legend{grid-template-columns:1fr;gap:10px}.sample-top{align-items:flex-start}.sample-top button{white-space:nowrap}.section-title{display:block}main{padding:18px 14px}.stop{margin-left:0}.track .wave{height:30px}}
</style></head><body>
<header><div class="eyebrow">Speech intelligence / Listening room</div><h1>听见目标，听清差别。</h1><p>同一段混音，同一个目标，三种模型。按目标人与干扰人的相对强弱，比较提取效果；再听目标不在场时，模型留下了什么。</p><div class="chips"><span>20组固定测试样本</span><span>3个模型 · 每组5路音频</span><span>16 kHz · 单麦 · 4秒</span><span>离线可用 · 音频已嵌入</span></div></header>
<main><div class="note"><strong>保留原始音量比例。</strong>没有对输出单独归一化或放大，输出变小也是模型表现的一部分。先用适中音量试听。波形在同一固定幅度刻度下绘制；音频以PCM16封装，未做增益补偿。</div>
<div class="legend"><div><strong>SIR：目标相对干扰的强弱</strong><p>负值：目标更弱；0 dB：等强；正值：目标更强。这里不额外添加噪声或混响。</p></div><div><strong>SI-SNRi：相对输入提升多少</strong><p>越大越好；不等于输出的绝对SI-SNR，也不反映输出音量是否保持。</p></div><div><strong>缺席抑制：非目标语音压低多少</strong><p>越大越好，0 dB表示基本没压低；但必须同时检查有目标时是否也被压低。</p></div></div>
<div class="toolbar"><div class="controls" id="sir-controls"><span class="caption">场景</span><button data-sir="all" aria-pressed="true">全部</button><button data-sir="-5" aria-pressed="false">−5 dB · 目标弱</button><button data-sir="0" aria-pressed="false">0 dB · 等强</button><button data-sir="5" aria-pressed="false">+5 dB</button><button data-sir="10" aria-pressed="false">+10 dB</button><button data-sir="20" aria-pressed="false">+20 dB</button><button data-sir="extreme" aria-pressed="false">极弱目标</button><button data-sir="absent" aria-pressed="false">目标缺席</button><button class="stop" id="stop">停止播放</button></div><div class="controls"><span class="caption">语料</span><select id="corpus" aria-label="筛选目标或注册说话人的语料"><option value="all">全部语料</option><option value="librispeech">LibriSpeech</option><option value="aishell1">AISHELL-1</option><option value="aishell2">AISHELL-2</option></select><span id="count" class="small" role="status"></span></div></div>
<div id="content"></div><div id="empty" hidden>当前筛选下没有样本。</div>
<footer><strong>样本与权重</strong><p>从固定独立测试集按SIR与语料分组后，取排序最前的样本ID；极弱目标各取一条，缺席每种注册语料各取一条。不按模型分数挑选，不代表完整测试集均值。缺席样本中注册人不在场，混音含两名其他说话人；标注语料对应注册人。−10/−20 dB低于训练SIR下限−5 dB，属于范围外测试。</p><div id="models"></div><p>所有模型使用FP32/eval推理、同一混音与声纹；权重按验证集选择，并非统一最后一轮。完整来源可展开每张卡片查看。</p><p>此HTML包含所有音频，无外部脚本、字体或网络依赖。生成日期：2026-11-11。</p></footer></main>
<script id="data" type="application/json">__DATA__</script>
<script>
const DATA=JSON.parse(document.getElementById('data').textContent),content=document.getElementById('content');
const corpusNames={librispeech:'LibriSpeech',aishell1:'AISHELL-1',aishell2:'AISHELL-2'};
const trackNames=[['mix','输入混音'],['target','干净目标'],...DATA.models.map(m=>[m.id,m.label])];
const groupInfo={'-5':['目标较弱','SIR −5 dB · 干扰功率约为目标的3.16倍'],'0':['两人等强','SIR 0 dB · 等RMS混合'],'5':['目标较强','SIR +5 dB · 目标功率约为干扰的3.16倍'],'10':['目标明显更强','SIR +10 dB · 目标功率为干扰的10倍'],'20':['目标远强于干扰','SIR +20 dB · 目标功率为干扰的100倍'],'-20':['极弱目标 · −20 dB','范围外测试 · 干扰功率约为目标的100倍'],'-10':['极弱目标 · −10 dB','范围外测试 · 干扰功率约为目标的10倍'],absent:['目标缺席 · 应当输出静音','注册人不在场，检查非目标语音残留']};
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function db(x){return (x>=0?'+':'')+x.toFixed(2)+' dB'}
let playlist=[],seq=0;function stop(){playlist=[];document.querySelectorAll('audio').forEach(a=>{a.pause();a.currentTime=0})}
function wave(env){const ns='http://www.w3.org/2000/svg',s=document.createElementNS(ns,'svg');s.setAttribute('viewBox','0 0 200 40');s.setAttribute('class','wave');s.setAttribute('aria-hidden','true');let p=document.createElementNS(ns,'path'),v='';env.forEach((x,i)=>{const h=Math.max(.3,Math.min(1,x)*19);v+=`M${i*2+1},${20-h}v${h*2} `});p.setAttribute('d',v);p.setAttribute('stroke','currentColor');p.setAttribute('stroke-width','1.3');s.append(p);return s}
const sections=[];
for(const group of ['-5','0','5','10','20','-20','-10','absent']){
 const section=el('section'),heading=el('div','section-title'),h=el('h2','',groupInfo[group][0]);heading.append(h,el('span','',groupInfo[group][1]));section.append(heading);const cards=[];
 for(const r of DATA.samples.filter(r=>r.group===group)){
  const card=el('article','sample'),top=el('div','sample-top'),info=el('div'),title=el('h3');title.append(el('span','badge'+(group==='absent'?' absent':''),corpusNames[r.metadata.corpus]),document.createTextNode(r.id));info.append(title,el('p','',group==='absent'?'注册人 '+r.metadata.target_speaker+' · 正确目标为全静音':'目标 '+r.metadata.target_speaker+' · SIR '+db(Number(group))));const play=el('button','','逐路试听');play.setAttribute('aria-label',r.id+' 连续播放混音、目标和三个模型输出');top.append(info,play);card.append(top);const grid=el('div','tracks'),audios=[];
  trackNames.forEach(([key,label])=>{
   const track=el('div','track '+(key==='mix'?'input':key==='target'?'target':'')),head=el('div','track-label'),model=DATA.models.find(m=>m.id===key);head.append(el('span','',label),el('small','',model?'E'+model.epoch:'4秒'));track.append(head,wave(r.tracks[key].envelope));const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src='data:audio/wav;base64,'+r.tracks[key].wav;audio.setAttribute('aria-label',r.id+' '+label);audio.addEventListener('play',()=>{if(playlist[seq]!==audio)playlist=[];document.querySelectorAll('audio').forEach(a=>{if(a!==audio)a.pause()})});audio.addEventListener('ended',()=>{if(playlist[seq]===audio&&seq+1<playlist.length){seq++;playlist[seq].currentTime=0;playlist[seq].play().catch(()=>{playlist=[]})}});audios.push(audio);track.append(audio);const metric=el('div','metric');
   if(model){const m=r.metrics[key];if(group==='absent'){metric.append(el('b',m.suppression_db<0?'negative':'',m.suppression_db.toFixed(2)+' dB'),el('span','',' 抑制'));metric.append(el('div','small','输出 RMS '+r.tracks[key].rms.toFixed(5)))}else{metric.append(el('b',m.sisnri_db<0?'negative':'',db(m.sisnri_db)),el('span','',' SI-SNRi'));metric.append(el('div','small','输出音量 '+db(m.gain_db)+'（相对目标）'))}}
   else if(key==='mix'){metric.textContent=group==='absent'?'只有其他人，无注册目标人':'输入 SI-SNR '+db(Object.values(r.metrics)[0].input_sisnr_db)}else metric.textContent=group==='absent'?'全零参考 · 播放应当无声':'理想输出 · 干净目标';track.append(metric);grid.append(track);
  });card.append(grid);play.onclick=()=>{stop();playlist=audios;seq=0;audios[0].currentTime=0;audios[0].play().catch(()=>{playlist=[]})};const details=el('details'),summary=el('summary','','查看来源与样本说明');details.append(summary,el('p','','场景：'+r.metadata.scenario+'；目标／注册说话人：'+r.metadata.target_speaker),el('p','','干扰说话人：'+r.metadata.interferer_speakers.join('、')),el('p','','注册录音：'+r.metadata.enrollment_path));r.metadata.source_paths.forEach(p=>details.append(el('p','','源录音：'+p)));details.append(el('p','','峰值缩放系数：'+r.metadata.peak_scale+'；试听未做额外增益处理。'));card.append(details);section.append(card);cards.push({card,corpus:r.metadata.corpus});
 }content.append(section);sections.push({section,group,cards});
}
let current='all';function filter(){stop();const corpus=document.getElementById('corpus').value;let n=0;sections.forEach(s=>{const match=current==='all'||current===s.group||(current==='extreme'&&['-20','-10'].includes(s.group));let visible=0;s.cards.forEach(c=>{const yes=match&&(corpus==='all'||corpus===c.corpus);c.card.hidden=!yes;if(yes)visible++});s.section.hidden=!visible;n+=visible});document.getElementById('count').textContent='显示 '+n+' / 20 组';document.getElementById('empty').hidden=n!==0}
document.querySelectorAll('[data-sir]').forEach(b=>b.onclick=()=>{current=b.dataset.sir;document.querySelectorAll('[data-sir]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()});document.getElementById('corpus').onchange=filter;document.getElementById('stop').onclick=stop;
DATA.models.forEach(m=>{const p=el('p','',m.label+' · '+m.id+' · epoch '+m.epoch+' · SHA256 '+m.sha256);p.style.wordBreak='break-all';document.getElementById('models').append(p)});filter();
</script></body></html>'''.replace('__DATA__',DATA)
path=folder/'TF_TSE_试听对比.html';path.write_text(html)
print(path,round(path.stat().st_size/1024/1024,2),'MiB; verified 100 PCM16 mono 4s tracks')
